import { ClientInvoiceStatus, type ClientInvoice } from "../../types/work-billing"
import type { ClientContract, ClientFollowUp, ClientNote } from "../../types/work-crm"
import type { SatisfactionResponse } from "../../types/work-feedback"
import { WorkProjectStatus, type WorkProject } from "../../types/work-projects"
import type { Deal, PipelineSettings } from "../../types/work-sales"
import { ClientStatus, type Client } from "../../types/workforce"
import { invoiceBalance, invoiceTotals, toBase } from "./billing"
import { clientOutstanding, contractStatus, creditStatus, daysOverdue } from "./client-relations"
import { isOpenDeal, weightedValue } from "./deals"
import { roundMoney } from "./money"
import { satisfactionStats } from "./satisfaction"

/**
 * One client's figures for the CRM list, the details panel and the client
 * page (CRM step 1), built from the existing records with the existing rules:
 * balance from clientOutstanding, open deals from isOpenDeal, satisfaction
 * from satisfactionStats, contracts from contractStatus.
 */

/** No meeting, call or note for this long and an active client needs a word. */
export const QUIET_AFTER_DAYS = 60
/** Invoices late by more than this put a client at risk; less is "watch". */
export const LATE_AT_RISK_DAYS = 30
/** Average stars under this are a warning. */
export const LOW_SATISFACTION = 3

export type HealthLevel = "good" | "watch" | "at_risk"
export type HealthReason = "late_payment" | "very_late_payment" | "over_credit_limit" | "low_satisfaction" | "quiet" | "renewal_due" | "late_follow_up"

const AT_RISK: HealthReason[] = ["very_late_payment", "over_credit_limit", "low_satisfaction"]

export interface ClientFigures {
  projects: { total: number; inProgress: number; completed: number; cancelled: number }
  openDeals: { count: number; amount: number; weighted: number }
  /** Issued this calendar year before VAT, credit notes deducted, in the base currency */
  billedThisYear: number
  /** Still owed, VAT included, in the base currency */
  outstanding: number
  /** Part of it past the due date */
  overdue: number
  /** Days late of the oldest unpaid invoice; 0 when nothing is late */
  oldestLateDays: number
  /** Last meeting, call or note (yyyy-mm-dd) */
  lastContact?: string
  /** The earliest follow-up still to do */
  nextFollowUp?: ClientFollowUp
  /** Follow-ups still to do whose date has passed */
  lateFollowUps: number
  satisfaction: ReturnType<typeof satisfactionStats> & { latest?: Pick<SatisfactionResponse, "rating" | "comment" | "respondentName" | "answeredAt"> }
  /** null for leads and archived clients: health concerns clients you work with */
  health: { level: HealthLevel; reasons: HealthReason[] } | null
}

export interface ClientRecords {
  /** The company's stage chances (CRM step 8); the defaults when unset */
  pipeline?: PipelineSettings
  invoices: ClientInvoice[]
  projects: WorkProject[]
  deals: Deal[]
  notes: ClientNote[]
  followUps: ClientFollowUp[]
  contracts: ClientContract[]
  responses: SatisfactionResponse[]
}

const daysBetween = (from: string, to: string) => Math.round((Date.parse(`${to}T00:00:00Z`) - Date.parse(`${from}T00:00:00Z`)) / 86_400_000)

export function clientFigures(client: Pick<Client, "id" | "status" | "creditLimit" | "createdAt">, r: ClientRecords, today: string): ClientFigures {
  const id = client.id
  const projects = r.projects.filter((p) => p.clientId === id)
  const deals = r.deals.filter((d) => d.clientId === id && isOpenDeal(d))
  const invoices = r.invoices.filter((i) => i.clientId === id)
  const year = today.slice(0, 4)

  const billedThisYear = roundMoney(
    invoices
      .filter((i) => i.status !== ClientInvoiceStatus.DRAFT && i.status !== ClientInvoiceStatus.VOID && i.issueDate.slice(0, 4) === year)
      .reduce((s, i) => s + toBase(invoiceTotals(i).subtotal, i), 0)
  )
  const outstanding = clientOutstanding(id, r.invoices)
  const late = invoices.map((i) => ({ i, balance: invoiceBalance(i, r.invoices) })).filter((x) => x.balance > 0 && x.i.dueDate < today)
  const overdue = roundMoney(late.reduce((s, x) => s + toBase(x.balance, x.i), 0))
  const oldestLateDays = late.reduce((m, x) => Math.max(m, daysOverdue(x.i, today)), 0)

  const contacts = r.notes.filter((n) => n.clientId === id && n.date <= today).map((n) => n.date)
  const lastContact = contacts.sort().at(-1)
  const open = r.followUps.filter((f) => f.clientId === id && !f.doneAt).sort((a, b) => a.dueDate.localeCompare(b.dueDate) || a.id.localeCompare(b.id))
  const lateFollowUps = open.filter((f) => f.dueDate < today).length

  const answers = r.responses.filter((x) => x.clientId === id).sort((a, b) => b.answeredAt.localeCompare(a.answeredAt))
  const latest = answers[0]
  const satisfaction = { ...satisfactionStats(answers), latest: latest ? { rating: latest.rating, comment: latest.comment, respondentName: latest.respondentName, answeredAt: latest.answeredAt } : undefined }

  let health: ClientFigures["health"] = null
  if (client.status === ClientStatus.ACTIVE) {
    const reasons: HealthReason[] = []
    if (oldestLateDays > LATE_AT_RISK_DAYS) reasons.push("very_late_payment")
    else if (oldestLateDays > 0) reasons.push("late_payment")
    if (creditStatus(client, outstanding).over) reasons.push("over_credit_limit")
    if (satisfaction.average !== null && satisfaction.average < LOW_SATISFACTION) reasons.push("low_satisfaction")
    // quiet: no contact for 60 days, counted from the client's creation when there was never any
    const since = lastContact ?? client.createdAt.slice(0, 10)
    if (daysBetween(since, today) > QUIET_AFTER_DAYS) reasons.push("quiet")
    if (r.contracts.some((c) => c.clientId === id && contractStatus(c, today) === "renewal_due")) reasons.push("renewal_due")
    if (lateFollowUps > 0) reasons.push("late_follow_up")
    health = { level: reasons.some((x) => AT_RISK.includes(x)) ? "at_risk" : reasons.length ? "watch" : "good", reasons }
  }

  return {
    projects: {
      total: projects.length,
      inProgress: projects.filter((p) => p.status === WorkProjectStatus.PLANNING || p.status === WorkProjectStatus.ACTIVE || p.status === WorkProjectStatus.ON_HOLD).length,
      completed: projects.filter((p) => p.status === WorkProjectStatus.COMPLETED).length,
      cancelled: projects.filter((p) => p.status === WorkProjectStatus.CANCELLED).length,
    },
    openDeals: { count: deals.length, amount: roundMoney(deals.reduce((s, d) => s + d.amount, 0)), weighted: roundMoney(deals.reduce((s, d) => s + weightedValue(d, r.pipeline), 0)) },
    billedThisYear,
    outstanding,
    overdue,
    oldestLateDays,
    lastContact,
    nextFollowUp: open[0],
    lateFollowUps,
    satisfaction,
    health,
  }
}

/** Every tag used in the workspace, most used first, for filters and suggestions. */
export function tagsInUse(clients: Pick<Client, "tags">[]) {
  const count = new Map<string, number>()
  for (const c of clients) for (const t of c.tags ?? []) count.set(t, (count.get(t) ?? 0) + 1)
  return [...count.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([tag]) => tag)
}

/** Tags as typed by people: trimmed, no duplicates whatever the case, at most 10 of 30 characters. */
export function cleanTags(tags: string[]) {
  const seen = new Set<string>()
  const out: string[] = []
  for (const raw of tags) {
    const t = raw.trim().replace(/\s+/g, " ").slice(0, 30)
    if (!t || seen.has(t.toLocaleLowerCase())) continue
    seen.add(t.toLocaleLowerCase())
    out.push(t)
  }
  return out.slice(0, 10)
}
